 "content": "def transform(grid):
    # Each isolated 6 is the top-left anchor for the 3x3 stamp.
    # Stamp colors from its upper-left corner are laid on blank background
    # cells; the anchor itself is replaced by the stamp's first color.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    pattern = [[8, 3, 0], [3, 0, 1], [0, 1, 1]]
    for r, c in anchors:
        for dr in range(3):
            for dc in range(3):
                rr, cc = r + dr, c + dc
                if rr < h and cc < w:
                    color = pattern[dr][dc]
                    if color != 1:
                        out[rr][cc] = color
    return out
